import asyncio

async def main():
    path = "nodes/34aaa432.txt"
    rows = []
    seen = []
    steps = 0
    while True:
        r = await yuki_workspace_read({"path": "/workspace/" + path})
        if not r['ok']:
            return {"error": r}
        text = r['data']['text']
        d = {}
        for line in text.splitlines():
            line = line.strip()
            if not line or '=' not in line:
                continue
            k, v = line.split('=', 1)
            d[k.strip()] = v.strip()
        rows.append((path, d.get('value')))
        steps += 1
        if steps > 500:
            return {"error": "too many steps", "rows": rows}
        val = int(d['value'])
        nxt = d['left'] if val % 2 == 0 else d['right']
        if nxt.upper() == 'END':
            break
        seen.append(nxt)
        path = nxt
    return {"rows": rows}

