import asyncio

files = ["ledger/%02d.csv" % i for i in range(24)]

async def readf(p):
    return await yuki_workspace_read({"path": "/workspace/" + p})

res = await asyncio.gather(*[readf(p) for p in files[:8]]) + \
      await asyncio.gather(*[readf(p) for p in files[8:16]]) + \
      await asyncio.gather(*[readf(p) for p in files[16:]])

# collect raw rows (with multiplicities) separately from dedup
raw_rows = []
for p, r in zip(files, res):
    for ln in r["data"]["text"].splitlines()[1:]:
        if ln.strip():
            raw_rows.append(tuple(ln.split(",")))

# dedup by id
dedup = {}
dups = 0
for id_, region, amount, status in raw_rows:
    if id_ in dedup:
        dups += 1
        assert dedup[id_] == (region, amount, status)
    else:
        dedup[id_] = (region, amount, status)

# status histogram
from collections import Counter
st = Counter(v[2] for v in dedup.values())
rg = Counter(v[0] for v in dedup.values())

agg = {}
for id_, (region, amount, status) in dedup.items():
    if status != "ok":
        continue
    a = agg.setdefault(region, [0, 0])
    a[0] += 1
    a[1] += int(amount)

print("raw rows:", len(raw_rows), "dup rows:", dups, "unique:", len(dedup))
print("status(dedup):", dict(st))
print("region counts(dedup incl void):", dict(rg))
for g in "ABCD":
    print(g, "ok_count =", agg[g][0], "sum =", agg[g][1])
